INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Qafila Creative Agency S.P.C.","nameAr":"وكالة قافلة الإبداعية ذ.م.م","shortEn":"Qafila Creative","shortAr":"قافلة الإبداعية","taglineEn":"Brand Identity, Campaigns & Digital Experience","taglineAr":"الهوية البصرية والحملات والتجربة الرقمية","aboutEn":"Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns.","aboutAr":"وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات."},"hero":{"titleEn":"Qafila Creative — Brand Identity, Campaigns & Digital Experience","titleAr":"قافلة الإبداعية — الهوية البصرية والحملات والتجربة الرقمية","ctaLabelEn":"Explore Qafila Creative","ctaLabelAr":"استكشف قافلة الإبداعية"},"featuredServices":[{"code":"SVC-BRD","en":"Complete Brand Identity System","ar":"تصميم نظام الهوية البصرية الكامل","rate":3200},{"code":"SVC-CMP","en":"Integrated Launch Campaign","ar":"حملة إطلاق متكاملة","rate":1850},{"code":"SVC-UXD","en":"Product UI/UX Design Sprint","ar":"تصميم واجهات وتجربة المستخدم","rate":950},{"code":"SVC-SOC","en":"Social Content & Retainer","ar":"إدارة المحتوى والتواصل الشهري","rate":1100}]}'::jsonb, '{"company":{"nameEn":"Qafila Creative Agency S.P.C.","nameAr":"وكالة قافلة الإبداعية ذ.م.م","shortEn":"Qafila Creative","shortAr":"قافلة الإبداعية","taglineEn":"Brand Identity, Campaigns & Digital Experience","taglineAr":"الهوية البصرية والحملات والتجربة الرقمية","aboutEn":"Independent brand and digital agency partnering with ambitious regional enterprises on strategy, design systems, and launch campaigns.","aboutAr":"وكالة مستقلة للعلامات التجارية والتجربة الرقمية تتعاون مع المؤسسات الطموحة في الاستراتيجية والتصميم والحملات."},"hero":{"titleEn":"Qafila Creative — Brand Identity, Campaigns & Digital Experience","titleAr":"قافلة الإبداعية — الهوية البصرية والحملات والتجربة